```rust
/// How long to wait between bind attempts.  Silence is deliberate: ...
const RETRY_INTERVAL: Duration = Duration::from_millis(100);

/// Bind `<dir>/console.sock`, retrying forever and silently.
fn bind_listener(dir: &str) -> (UnixDatagram, PathBuf) {
    let path = PathBuf::from(dir).join(SOCKET_NAME);
    loop {
        if let Some(sock) = try_bind(&path) {
            return (sock, path);
        }
        thread::sleep(RETRY_INTERVAL);
    }
}

fn try_bind(path: &Path) -> Option<UnixDatagram> {
    if let Some(dir) = path.parent() {
        let _ = std::fs::create_dir_all(dir);
    }
    match UnixDatagram::bind(path) {
        Ok(sock) => Some(sock),
        Err(e) if e.kind() == ErrorKind::AddrInUse => {
            // A previous run died without unlinking its socket file; the
            // path is stale by definition (System A broadcasts only, it
            // never binds here).  Clear it and try again once.
            let _ = std::fs::remove_file(path);
            UnixDatagram::bind(path).ok()
        }
        Err(_) => None,
    }
}
```

Note: "the path is stale by definition" is not strictly true if another console instance is alive. Rephrase: "might be stale; System A only broadcasts, so the file is never useful to anyone but a listener that owns the FD". Keep honest: "the only writer of this name is a previous instance of this console; a stale file from a crashed run must not block startup forever. A second live instance would take over the name — the newest console wins."

